Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='neversecretexpand', at=datetime(2026, 11, 26, 0, 0, 0), actor='assistant', title='Never expand a secret in a command that prints', body='Test that a secret is set with a bare test of non-empty, and print its length alone. Do not use a default-value expansion in any printed expression, because it prints the value when the variable is set. Prefer a check command that lists names and set or unset only. If a value leaks into a transcript, scrub the local copy and rotate the secret.', rationale='Command output becomes a permanent record, and a leak into a remote record cannot be scrubbed.', supersedes=()))